llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C52"],
      "claim": "Maraviroc showed an absolute oral bioavailability of 33% at a 300 mg dose in uninfected volunteers, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Perindopril had an absolute oral bioavailability of about 75% after oral administration, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "In young healthy subjects, the measured bioavailability was 19% ± 7%, a point estimate below the 20% threshold but with uncertainty spanning it.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transfer evidence shows absolute oral bioavailability values clearly above 20%, while the only sub-threshold record is uncertain and endpoint-limited; therefore F >= 20% is better supported.",
  "evidence_gaps": [
    "Molecule 1's sub-threshold record (C48) is for a metabolite after prodrug administration and has a large uncertainty (19 ± 7%) spanning the 20% threshold.",
    "Molecule 9 provides only qualitative 'high' bioavailability without a numeric threshold-specific value.",
    "Some positive records come from altered populations or use systemic availability rather than absolute oral bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

